#pragma once
#include <cstdint>
namespace ks{class PanelByteTask final{public:enum class Kind{CommandWrite,CommandRead,DataWrite,DataRead};enum class Stage{Hold,ClearGate,DisableGate,SelectControl,WriteControl,EnableControl,WriteEnable,Transfer,WaitFirst,WaitSecond,WaitThird,WaitFourth,RestoreControl,WriteRestore,SetGate,RestoreGate,RestoreHeld,Finish,Complete};enum class Read{Input,Data};enum class Port{Gate,Control,Data};explicit PanelByteTask(Kind k):kind_(k){}Kind kind()const{return kind_;}Stage stage()const{return stage_;}bool reading()const{return kind_==Kind::CommandRead||kind_==Kind::DataRead;}uint8_t control()const{return kind_==Kind::CommandWrite?0x30:kind_==Kind::CommandRead?0x32:kind_==Kind::DataWrite?0x31:0x33;}uint8_t data()const{return data_;}
template<class Clock>unsigned nextClocks(Clock&&clock)const{switch(stage_){case Stage::Hold:case Stage::RestoreHeld:return 11;case Stage::DisableGate:case Stage::RestoreGate:return 6+clock(Port::Gate);case Stage::WriteControl:case Stage::WriteEnable:case Stage::WriteRestore:return 3+clock(Port::Control);case Stage::Transfer:return 3+(reading()?1:clock(Port::Data));case Stage::Finish:return 17;case Stage::Complete:return 0;default:return 3;}}
template<class Reader,class Writer,class Clock>unsigned advanceBefore(unsigned available,Reader&&read,Writer&&write,Clock&&clock){unsigned used=0;while(auto cost=nextClocks(clock)){if(cost>available-used)break;switch(stage_){case Stage::Hold:stage_=reading()?Stage::ClearGate:Stage::SelectControl;break;case Stage::ClearGate:stage_=Stage::DisableGate;break;case Stage::DisableGate:write(Port::Gate,0);stage_=Stage::SelectControl;break;case Stage::SelectControl:stage_=Stage::WriteControl;break;case Stage::WriteControl:write(Port::Control,control());stage_=Stage::EnableControl;break;case Stage::EnableControl:stage_=Stage::WriteEnable;break;case Stage::WriteEnable:write(Port::Control,uint8_t(control()+8));stage_=reading()?Stage::WaitFirst:Stage::Transfer;break;case Stage::Transfer:data_=uint8_t(read(reading()?Read::Data:Read::Input));if(!reading())write(Port::Data,data_);stage_=reading()?Stage::RestoreControl:Stage::WaitFirst;break;case Stage::WaitFirst:stage_=Stage::WaitSecond;break;case Stage::WaitSecond:stage_=Stage::WaitThird;break;case Stage::WaitThird:stage_=Stage::WaitFourth;break;case Stage::WaitFourth:stage_=reading()?Stage::Transfer:Stage::RestoreControl;break;case Stage::RestoreControl:stage_=Stage::WriteRestore;break;case Stage::WriteRestore:write(Port::Control,control());stage_=reading()?Stage::SetGate:Stage::RestoreHeld;break;case Stage::SetGate:stage_=Stage::RestoreGate;break;case Stage::RestoreGate:write(Port::Gate,255);stage_=Stage::RestoreHeld;break;case Stage::RestoreHeld:stage_=Stage::Finish;break;case Stage::Finish:stage_=Stage::Complete;break;default:break;}used+=cost;}return used;}private:Kind kind_;Stage stage_=Stage::Hold;uint8_t data_=0;};}
